  "inlineSchema": "// ============================================================\n//  Schéma Prisma — Gestion Clinique\n//  Base : bd_clinique (SQL Server 2022 Express)\n//  Périmètre actuel : module Paramétrage (cf. cahier des charges §16)\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlserver\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ---------- Établissement (multi-clinique, §16.2) ----------\nmodel Clinique {\n  id        Int      @id @default(autoincrement())\n  code      String   @unique\n  nom       String\n  adresse   String?\n  telephone String?\n  statut    String   @default(\"ACTIF\") // ACTIF / INACTIF\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  services    Service[]\n  personnel   Personnel[]\n  prestations Prestation[]\n  parametre   Parametre?\n  patients    Patient[]\n  passages    Passage[]\n\n  @@map(\"cliniques\")\n}\n\n// ---------- Patients ----------\nmodel Patient {\n  id            Int      @id @default(autoincrement())\n  cliniqueId    Int\n  numeroDossier String // unique par clinique\n  code          String   @unique // code unique PERMANENT du patient (ex. P-9N7Z5A) : clé de recherche à vie\n  nom           String\n  prenom        String\n  age           String?\n  sexe          String? // M / F\n  ville         String?\n  quartier      String?\n  profession    String?\n  telephone     String?\n  createdAt     DateTime @default(now())\n  updatedAt     DateTime @updatedAt\n\n  clinique Clinique  @relation(fields: [cliniqueId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  passages Passage[]\n\n  @@unique([cliniqueId, numeroDossier])\n  @@map(\"patients\")\n}\n\n// ---------- Passages (le N° d'ordre expire après 10 jours ; le code du patient est permanent) ----------\nmodel Passage {\n  id                 Int      @id @default(autoincrement())\n  cliniqueId         Int\n  patientId          Int\n  numeroOrdre        String // ex. MED-001092026 (code service + ordre/mois/année)\n  serviceId          Int\n  typePatient        String   @default(\"INTERNE\") // INTERNE / EXTERNE\n  motif              String?\n  referent           String? // patient externe : structure/professionnel référent\n  prestationDemandee String? // patient externe : prestation demandée\n  statut             String   @default(\"EN_ATTENTE_PAIEMENT\") // CREE, EN_ATTENTE_PAIEMENT, ACTIF, UTILISE, CLOTURE, EXPIRE\n  // Constantes saisies à l'accueil (§5.1)\n  taille             String?\n  temperature        Decimal? @db.Decimal(4, 1)\n  pouls              Int?\n  tensionGauche      String? // ex. 12/8\n  tensionDroite      String?\n  poids              Decimal? @db.Decimal(5, 1)\n  expireLe           DateTime // validité : 10 jours (§4.3)\n  createdAt          DateTime @default(now())\n  updatedAt          DateTime @updatedAt\n\n  patient  Patient  @relation(fields: [patientId], references: [id], onDelete: Cascade)\n  service  Service  @relation(fields: [serviceId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  clinique Clinique @relation(fields: [cliniqueId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n\n  @@unique([cliniqueId, numeroOrdre])\n  @@map(\"passages\")\n}\n\n// ---------- Paramètres de la clinique (ex. image de la page de connexion) ----------\nmodel Parametre {\n  id         Int      @id @default(autoincrement())\n  cliniqueId Int      @unique\n  loginImage String?  @db.NVarChar(Max) // image au format data URL (base64)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  clinique Clinique @relation(fields: [cliniqueId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n\n  @@map(\"parametres\")\n}\n\n// ---------- Services de la clinique ----------\nmodel Service {\n  id          Int      @id @default(autoincrement())\n  cliniqueId  Int\n  code        String // code court (ex. MED, LAB, IMA) — sert aussi au N° d'ordre\n  nom         String\n  description String?\n  actif       Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // NoAction : évite les chemins de cascade multiples (SQL Server)\n  clinique    Clinique     @relation(fields: [cliniqueId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  personnel   Personnel[]\n  prestations Prestation[]\n  passages    Passage[]\n\n  @@unique([cliniqueId, code])\n  @@map(\"services\")\n}\n\n// ---------- Personnel (fiche RH, §16.3) ----------\nmodel Personnel {\n  id           Int       @id @default(autoincrement())\n  cliniqueId   Int\n  matricule    String // unique par clinique (§16.2)\n  nom          String\n  prenom       String\n  sexe         String? // M / F\n  photo        String?   @db.NVarChar(Max) // photo du membre du personnel (data URL base64)\n  fonction     String // médecin, agent d'accueil, pharmacien...\n  serviceId    Int?\n  telephone    String?\n  email        String?\n  statut       String    @default(\"ACTIF\") // ACTIF / INACTIF\n  dateEmbauche DateTime? @db.Date\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  clinique    Clinique     @relation(fields: [cliniqueId], references: [id], onDelete: Cascade)\n  service     Service?     @relation(fields: [serviceId], references: [id])\n  utilisateur Utilisateur?\n\n  @@unique([cliniqueId, matricule])\n  @@map(\"personnel\")\n}\n\n// ---------- Utilisateurs (comptes de connexion, §16.2/16.3) ----------\nmodel Utilisateur {\n  id                Int       @id @default(autoincrement())\n  personnelId       Int       @unique\n  matricule         String    @unique // login\n  motDePasse        String // hash bcrypt\n  roleId            Int\n  statut            String    @default(\"ACTIF\") // ACTIF / SUSPENDU\n  derniereConnexion DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  personnel Personnel @relation(fields: [personnelId], references: [id], onDelete: Cascade)\n  role      Role      @relation(fields: [roleId], references: [id])\n\n  @@map(\"utilisateurs\")\n}\n\n// ---------- Rôles ----------\nmodel Role {\n  id          Int      @id @default(autoincrement())\n  code        String   @unique // ADMINISTRATEUR, ACCUEIL, CAISSE, MEDECIN...\n  nom         String\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  utilisateurs  Utilisateur[]\n  habilitations RoleModule[]\n\n  @@map(\"roles\")\n}\n\n// ---------- Modules applicatifs ----------\nmodel Module {\n  id          Int     @id @default(autoincrement())\n  code        String  @unique // ACCUEIL, CAISSE, CONSULTATION...\n  nom         String\n  description String?\n\n  habilitations RoleModule[]\n\n  @@map(\"modules\")\n}\n\n// ---------- Habilitations rôle ↔ module (§16) ----------\nmodel RoleModule {\n  roleId     Int\n  moduleId   Int\n  lecture    Boolean @default(true)\n  ecriture   Boolean @default(true)\n  validation Boolean @default(false)\n\n  role   Role   @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  module Module @relation(fields: [moduleId], references: [id], onDelete: Cascade)\n\n  @@id([roleId, moduleId])\n  @@map(\"roles_modules\")\n}\n\n// ---------- Prestations et tarifs ----------\nmodel Prestation {\n  id         Int      @id @default(autoincrement())\n  cliniqueId Int\n  serviceId  Int\n  code       String\n  libelle    String\n  type       String // CONSULTATION, EXAMEN_LABO, IMAGERIE, SOIN, MATERNITE, HOSPITALISATION, MEDICAMENT, AUTRE\n  montant    Decimal  @db.Decimal(18, 2)\n  actif      Boolean  @default(true)\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  clinique Clinique @relation(fields: [cliniqueId], references: [id], onDelete: Cascade)\n  service  Service  @relation(fields: [serviceId], references: [id])\n\n  @@unique([cliniqueId, code])\n  @@map(\"prestations\")\n}\n",
